WITH enriched AS (SELECT *, LAST_VALUE(amount, TRUE) OVER (ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_amount, FIRST_VALUE(merchant) IGNORE NULLS OVER (PARTITION BY merchant ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_merchant, ROW_NUMBER() OVER (ORDER BY txn_time, id) AS seq_no, LEAD(amount, 1) OVER (PARTITION BY txn_type ORDER BY amount, id) AS next_amount, AVG(amount) OVER (PARTITION BY account_id, merchant ORDER BY txn_time, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS amount_avg_5_prior FROM transactions) SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, last_known_amount, first_known_merchant, CASE WHEN txn_type RLIKE '^(REFUND|DEBIT)$' THEN 'CORE' WHEN txn_type RLIKE '^(CREDIT|FEE)$' THEN 'EXTENDED' ELSE 'PRIORITY' END AS txn_type_zone FROM enriched ORDER BY amount DESC NULLS LAST
